     1→use anyhow::Result;
     2→use eth1_api::ApiController;
     3→use fork_choice_control::Wait;
     4→use helper_functions::misc;
     5→use log::{debug, info, warn};
     6→use prometheus_metrics::Metrics;
     7→use std::sync::Arc;
     8→use typenum::Unsigned as _;
     9→use types::{fulu::containers::DataColumnIdentifier, phase0::primitives::H256, preset::Preset};
    10→
    11→use crate::misc::PoolTask;
    12→pub struct ReconstructDataColumnSidecarsTask<P: Preset, W: Wait> {
    13→    pub controller: ApiController<P, W>,
    14→    pub wait_group: W,
    15→    pub block_root: H256,
    16→    pub metrics: Option<Arc<Metrics>>,
    17→}
    18→
    19→impl<P: Preset, W: Wait> PoolTask for ReconstructDataColumnSidecarsTask<P, W> {
    20→    type Output = ();
    21→
    22→    async fn run(self) -> Result<Self::Output> {
    23→        let Self {
    24→            controller,
    25→            wait_group,
    26→            block_root,
    27→            metrics,
    28→        } = self;
    29→
    30→        let Ok(available_columns) = controller.data_column_sidecars_by_ids(
    31→            (0..P::NumberOfColumns::U64).map(|index| DataColumnIdentifier { block_root, index }),
    32→        ) else {
    33→            warn!("failed to retrieve data column sidecar from storage");
    34→            return Ok(());
    35→        };
    36→
    37→        if available_columns.len() == P::NumberOfColumns::USIZE {
    38→            debug!("no need to reconstruct data columns: {block_root:?}");
    39→            return Ok(());
    40→        }
    41→
    42→        if available_columns.len() * 2 < P::NumberOfColumns::USIZE {
    43→            warn!(
    44→                "cannot start reconstruction for block {block_root:?}: \
    45→                insufficient data columns (available: {})",
    46→                available_columns.len(),
    47→            );
    48→
    49→            return Ok(());
    50→        }
    51→
    52→        debug!("starting reconstruction for block: {block_root:?}");
    53→
    54→        let _columns_reconstruction_timer = metrics
    55→            .as_ref()
    56→            .map(|metrics| metrics.columns_reconstruction_time.start_timer());
    57→
    58→        let reconstructed_count = P::NumberOfColumns::USIZE.saturating_sub(available_columns.len());
    59→        let partial_matrix = available_columns
    60→            .into_iter()
    61→            .flat_map(|sidecar| misc::compute_matrix_for_data_column_sidecar(&sidecar))
    62→            .collect::<Vec<_>>();
    63→
    64→        match eip_7594::recover_matrix(&partial_matrix, controller.store_config().kzg_backend) {
    65→            Ok(full_matrix) => {
    66→                info!("reconstructed missing data columns for block: {block_root:?}");
    67→                controller.on_reconstruction(wait_group, block_root, full_matrix);
    68→
    69→                if let Some(metrics) = metrics.as_ref() {
    70→                    metrics
